BEGIN;

-- ── videography ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.partner_videography_profiles (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vendor_id   UUID NOT NULL REFERENCES public.vendors(id) ON DELETE CASCADE,
  service_id  UUID REFERENCES public.vendor_services(id) ON DELETE CASCADE,
  trade_id    TEXT NOT NULL DEFAULT 'videography' CHECK (trade_id = 'videography'),
  schema_version INTEGER NOT NULL DEFAULT 1,
  specialties                  TEXT[],
  events                       TEXT[],
  years                        NUMERIC,
  showreel                     TEXT,
  portfolio                    TEXT[],
  equipment                    TEXT[],
  service_radius_km            NUMERIC,
  source_specs JSONB,
  backfilled_at  TIMESTAMPTZ,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_videography_profile_service
  ON public.partner_videography_profiles (service_id) WHERE service_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_videography_profile_vendor ON public.partner_videography_profiles (vendor_id);

COMMENT ON COLUMN public.partner_videography_profiles.specialties IS
  'Specialties [required]';
COMMENT ON COLUMN public.partner_videography_profiles.events IS
  'Events [required]';
COMMENT ON COLUMN public.partner_videography_profiles.years IS
  'Years of experience [required]';
COMMENT ON COLUMN public.partner_videography_profiles.showreel IS
  'Showreel link [required]';
COMMENT ON COLUMN public.partner_videography_profiles.portfolio IS
  'Portfolio stills';
COMMENT ON COLUMN public.partner_videography_profiles.equipment IS
  'Equipment';
COMMENT ON COLUMN public.partner_videography_profiles.service_radius_km IS
  'Service area radius [required]';

ALTER TABLE public.partner_videography_profiles ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS partner_videography_profiles_owner ON public.partner_videography_profiles;
CREATE POLICY partner_videography_profiles_owner ON public.partner_videography_profiles FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_videography_profiles.vendor_id AND v.profile_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.vendors v WHERE v.id = partner_videography_profiles.vendor_id AND v.profile_id = auth.uid()));

DROP POLICY IF EXISTS partner_videography_profiles_operator ON public.partner_videography_profiles;
CREATE POLICY partner_videography_profiles_operator ON public.partner_videography_profiles FOR ALL TO authenticated
  USING (public.caller_is_operator()) WITH CHECK (public.caller_is_operator());

